package seneca.consola;

import seneca.parte1.*;
import java.time.*;
import java.util.*;
public final class ConsolaAdmin extends ConsolaBase {
    public static void main(String[] args){new ConsolaAdmin().ejecutar();}
    protected boolean admite(Usuario u){return u instanceof Administrador;}
    protected boolean puedeInicializar(){return true;}
    private Administrador admin(){return (Administrador)usuarioActual;}
    public void mostrarMenu(){while(true){System.out.println("0 Salir | 1 Crear torneo | 2 Ranking | 3 Liberar cupos | 4 Iniciar | 5 Resultado | 6 Finalizar | 7 Historial | 8 Premio entregado | 9 Alta usuario | 10 Baja usuario | 11 Equipo | 12 Instalacion | 13 Producto | 14 Stock | 15 Turno | 16 Reportes | 17 Baja equipo | 18 Baja turno | 19 Sugerencias | 20 Limite academia");int op=entero("Opcion: ",0,20);if(op==0)return;seguro(()->acciones(op));}}
    private void acciones(int op){switch(op){
        case 1->crearTorneo();case 2->{Torneo t=torneo();if(si("Usar ranking ELO individual"))club.configurarRankingElo(admin(),t.getId());else{int n=entero("Numero de participantes con ranking: ",0,1000);List<String> r=new ArrayList<>();for(int j=0;j<n;j++)r.add(texto("ID participante (J:login, J:login1|login2 ordenados, E:nombre): "));club.configurarRankingTorneo(admin(),t.getId(),r);}}
        case 3->club.liberarCuposTorneo(admin(),torneo().getId());case 4->club.iniciarTorneo(admin(),torneo().getId());case 5->{Torneo t=torneo();EncuentroTorneo e=elegir(t.getEncuentros().stream().filter(x->!x.isFinalizado()).toList(),EncuentroTorneo::toString);club.registrarResultadoTorneo(admin(),t.getId(),e.getId(),entero("Local: ",0,100000),entero("Visitante: ",0,100000));}case 6->club.finalizarTorneo(admin(),torneo().getId());case 7->consultarTorneos();case 8->club.marcarPremioEntregado(admin(),torneo().getId());case 9->alta();case 10->club.darBajaUsuario(admin(),usuario());
        case 11->club.crearEquipo(admin(),new Equipo(texto("Nombre: "),entero("Cupo: ",1,1000),deporte(),new Categoria(texto("Categoria: ")),new ArrayList<>()));
        case 12->club.registrarInstalacion(admin(),new Instalacion(texto("Nombre: "),texto("Tipo: "),entero("Capacidad: ",2,1000),deporte(),si("Techada"),true));
        case 13->club.registrarProducto(admin(),producto());case 14->{ArticuloTienda p=elegir(club.getComercial().getCatalogo().stream().filter(x->x instanceof ArticuloTienda).map(x->(ArticuloTienda)x).toList(),Producto::getNombre);if(si("Reabastecer"))club.reabastecer(admin(),p,entero("Cantidad: ",1,100000),texto("Ubicacion: "));else club.moverArticulo(admin(),p,texto("Origen: "),texto("Destino: "),entero("Cantidad: ",1,100000));}
        case 15->{Empleado e=elegir(club.getUsuarios().stream().filter(x->x instanceof Empleado&&x.isActivo()).map(x->(Empleado)x).toList(),Usuario::getLogin);club.getAdministrativo().crearTurno(admin(),e,texto("Dia: "),texto("Inicio HH:MM: "),texto("Fin HH:MM: "));}case 16->{System.out.println(club.reporteDeportivo(admin()));System.out.println(club.ingresosPorRubro(admin(),new Date(0),new Date()));System.out.println("Cobertura completa: "+club.getAdministrativo().coberturaCompleta());}
        case 17->club.darBajaEquipo(admin(),equipo());case 18->club.getAdministrativo().darBajaTurno(admin(),elegir(club.getAdministrativo().getTurnos().stream().filter(Turno::isActivo).toList(),x->x.getEmpleado().getLogin()+" "+x.getDia()+" "+x.getHoraInicio()));
        case 19->{Sugerencia s=elegir(club.getAdministrativo().getSugerencias(),Sugerencia::getNombre);boolean aprobar=si("Aprobar");club.decidirSugerencia(admin(),s,aprobar,aprobar?producto():null);}case 20->club.configurarLimiteAcademias(admin(),deporte(),entero("Limite: ",1,1000));
    }}
    private void crearTorneo(){String id=texto("ID: "),nombre=texto("Nombre: ");LocalDate fecha=LocalDate.parse(texto("Fecha AAAA-MM-DD: "));int cupo=entero("Cupos: ",2,256);Deporte d=deporte();Categoria cat=new Categoria(texto("Categoria o nivel: "));ModalidadTorneo m=ModalidadTorneo.values()[entero("1 Individual, 2 Dobles, 3 Equipos: ",1,3)-1];Torneo t=si("Competitivo")?new TorneoCompetitivo(id,nombre,fecha,cupo,d,cat,m,decimal("Tarifa: ")):new TorneoRecreativo(id,nombre,fecha,cupo,d,cat,m,decimal("Descuento fraccion: "));club.crearTorneo(admin(),t);}
    private void alta(){int rol=entero("1 Socio, 2 Entrenador, 3 Fisioterapeuta, 4 Estudiante, 5 Externo, 6 Admin: ",1,6);Usuario u=switch(rol){case 1->{Socio s=new Socio();s.setEdad(entero("Edad: ",0,120));yield s;}case 2->new Entrenador();case 3->new Fisioterapeuta();case 4->{Estudiante s=new Estudiante();s.setCodigoEstudiantil(texto("Codigo: "));s.setMatriculado(si("Matriculado"));yield s;}case 5->{Externo e=new Externo();e.setNombre(texto("Nombre: "));e.setDocumento(texto("Documento: "));yield e;}default->new Administrador();};u.setLogin(texto("Login: "));u.setPassword(texto("Clave: "));if(u instanceof Empleado e)e.setCodigoDescuento(texto("Codigo descuento: "));club.registrarUsuario(admin(),u);}
    private Producto producto(){Producto p=switch(entero("1 Articulo, 2 Bebida, 3 Snack: ",1,3)){case 1->new ArticuloTienda(texto("Categoria: "),0);case 2->new Bebida(si("Caliente"));default->new Snack(texto("Alergenos (ninguno si no aplica): "));};p.setNombre(texto("Nombre: "));p.setPrecio(decimal("Precio: "));p.setActivo(true);return p;}
}
